								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2 class="mb-4 text-center text-base font-semibold text-ui-heading">
								Filter CMO Dashboard FID / FPD
							</h2>

							<div class="max-h-[60vh] space-y-4 overflow-y-auto pb-1">
								<div>
									<p
										class="mb-2 text-2xs font-semibold uppercase tracking-wide text-ui-ink-gray-400"
									>
										Bulan
									</p>
									<div class="grid grid-cols-3 gap-2">
										<button
											v-for="(nama, i) in BULAN"
											:key="nama"
											type="button"
											class="rounded-xl px-2 py-2 text-xs font-semibold transition-colors"
											:class="
												draft.bulan === i + 1
													? 'bg-primary text-ui-onPrimary'
													: 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
											"
											@click="draft.bulan = i + 1"
										>
											{{ nama.slice(0, 3) }}
										</button>
									</div>
								</div>

								<div>
									<p
										class="mb-2 text-2xs font-semibold uppercase tracking-wide text-ui-ink-gray-400"
									>
										Tahun
									</p>
									<div class="flex flex-wrap gap-2">
										<button
											v-for="y in yearOptions"
											:key="y"
											type="button"
											class="rounded-full px-3.5 py-1.5 text-xs font-semibold transition-colors"
											:class="
												draft.tahun === y
													? 'bg-primary text-ui-onPrimary'
													: 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
											"
											@click="draft.tahun = y"
										>
											{{ y }}
										</button>
									</div>
								</div>
							</div>

							<div class="mt-4 flex gap-2">
								<button
									type="button"
									class="flex-1 rounded-2xl border border-ui-line-gray-200 py-3 text-xs font-semibold text-ui-ink-gray-600 active:bg-ui-surface-gray-50"
									@click="resetFilter"
								>
									Bulan ini
								</button>
								<button
									type="button"
									class="flex-[2] rounded-2xl bg-primary py-3 text-xs font-semibold text-ui-onPrimary active:opacity-90"
									@click="applyFilter"
								>
									Terapkan
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { call } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { notifyError } from '../composables/toast'
import { clampPct, fmtNum, fmtNumFixed } from '../composables/realisasiFormat'
import { useListPersistence } from '../composables/useListPersistence'

const listPersistence = useListPersistence('CmoFidFpdDashboard')

// Pembungkus portal, bukan API desk langsung: isinya tetap dari desk apa adanya,
// tapi penolakannya dijaga server sehingga URL halaman ini tidak bisa dibuka
// oleh yang bukan CMO.
const API = 'juragan.api.portal.cmo_dashboard_fid_fpd'

// Magenta keunguan — membedakan dashboard ini dari empat kartu lain di Home.
const CMO_FF_GRADIENT = 'linear-gradient(135deg, #35152e 0%, #78214f 55%, #c2417a 100%)'

const BULAN = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
const GRACE = [0, 7, 15, 30]
const KATEGORI = [
	{ value: 'all', short: 'All' },
	{ value: 'mokas', short: 'Mokas' },
	{ value: 'enduser', short: 'End User' },
]
// Empat kolom seperti desk: unit dan persen berdampingan untuk tiap metrik.
const HEATMAP_KOLOM = [
	{ key: 'fid_unit', label: 'FID', mode: 'fid', display: 'unit' },
	{ key: 'fid_pct', label: 'FID (%)', mode: 'fid', display: 'pct' },
	{ key: 'fpd_unit', label: 'FPD', mode: 'fpd', display: 'unit' },
	{ key: 'fpd_pct', label: 'FPD (%)', mode: 'fpd', display: 'pct' },
]

// Palet & ambang warna heatmap SAMA dengan desk (heatmapColor): ambangnya
// berbeda antara FID dan FPD karena skala wajarnya memang tidak sama.
const HEATMAP_AMBANG = { fid: [1.5, 2.5, 3.5, 5], fpd: [0.5, 1, 1.5, 2] }
const HEATMAP_PALET = [
	{ bg: '#EBF5FF', fg: '#1059A8' },
	{ bg: '#BAD9F8', fg: '#1059A8' },
	{ bg: '#6FB3F2', fg: '#FFFFFF' },
	{ bg: '#2490EF', fg: '#FFFFFF' },
	{ bg: '#1059A8', fg: '#FFFFFF' },
]

const KATEGORI_SISI = [
	{ key: 'mokas', label: 'Mokas', color: '#4F52E5', soft: 'rgba(79,82,229,0.08)' },
	{ key: 'enduser', label: 'End User', color: '#34C28A', soft: 'rgba(52,194,138,0.10)' },
]

const now = new Date()
const loading = ref(false)
const fatalError = ref('')
const showFilter = ref(false)
const kategori = ref('all')
const heatmapKategori = ref('all')
const heatmapGrace = ref(0)

const filters = reactive({ bulan: now.getMonth() + 1, tahun: now.getFullYear() })
const draft = reactive({ ...filters })

const opsi = ref(null)
const kpi = ref(null)
const prev = ref(null)
const line = ref(null)
const breakdown = ref(null)
const heatmap = ref(null)

const periodeLabel = computed(() => `${BULAN[filters.bulan - 1]} ${filters.tahun}`)
const cabangLabel = computed(() => opsi.value?.cabang || 'Cabang saya')
const scopeLabel = computed(() => {
	const o = opsi.value
	if (!o?.nama_lengkap) return 'Pencapaian saya'
	return o.cabang ? `${o.nama_lengkap} · ${o.cabang}` : o.nama_lengkap
})

const yearOptions = computed(() => {
	const min = Number(opsi.value?.min_year) || now.getFullYear()
	const max = Math.max(Number(opsi.value?.current_year) || now.getFullYear(), filters.tahun)
	const years = []
	for (let y = max; y >= min; y--) years.push(y)
	return years
})

const activeFilterCount = computed(() =>
	filters.bulan !== now.getMonth() + 1 || filters.tahun !== now.getFullYear() ? 1 : 0,
)

const metrikUtama = computed(() => {
	const k = kpi.value || {}
	return [
		{
			key: 'FID',
			color: '#fb923c',
			pct: k.fid?.pct,
			delta: k.fid?.pct_delta,
			unit: k.fid?.unit,
			denominator: k.fid?.denominator,
		},
		{
			key: 'FPD',
			color: '#f87171',
			pct: k.fpd?.pct,
			delta: k.fpd?.pct_delta,
			unit: k.fpd?.unit,
			denominator: k.fpd?.denominator,
		},
	]
})

const rincian = computed(() => {
	const k = kpi.value || {}
	return [
		{
			key: 'FID',
			color: '#f97316',
			items: [
				{ label: 'Populasi', value: k.fid?.target_all },
				{ label: 'Selesai', value: k.fid?.done },
				{ label: 'Partial', value: k.fid?.partial },
				{ label: 'Tarikan', value: k.fid?.tarikan },
			],
		},
		{
			key: 'FPD',
			color: '#dc2626',
			items: [
				{ label: 'Populasi', value: k.fpd?.target_all },
				{ label: 'Selesai', value: k.fpd?.done },
				{ label: 'Tarikan', value: k.fpd?.tarikan },
			],
		},
	]
})

// Bulan sebelumnya: berapa yang akhirnya selesai dalam toleransi.
const metrikCutOff = computed(() => {
	const p = prev.value
	if (!p) return []
	return [
		{ key: 'FID', color: '#f97316', ...(p.fid || {}) },
		{ key: 'FPD', color: '#dc2626', ...(p.fpd || {}) },
	].map((m) => ({
		...m,
		pct_selesai: m.unit ? ((Number(m.selesai) || 0) / m.unit) * 100 : null,
	}))
})

const trenBulan = computed(() => {
	const d = line.value
	if (!d) return []
	return (d.labels || []).map((label, i) => ({
		label: label.slice(0, 3),
		fid: Number(d.fid_pct?.[kategori.value]?.[i]) || 0,
		fpd: Number(d.fpd_pct?.[kategori.value]?.[i]) || 0,
	}))
})

// Skala sumbu Y dibulatkan ke atas ke kelipatan 5 supaya garis bantunya rapi.
const maxTren = computed(() => {
	const tertinggi = Math.max(1, ...trenBulan.value.flatMap((m) => [m.fid, m.fpd]))
	return Math.ceil(tertinggi / 5) * 5 || 5
})

const TREN_W = 300
const TREN_H = 120

function trenX(i) {
	const n = Math.max(1, trenBulan.value.length - 1)
	return (i / n) * TREN_W
}

function trenY(v) {
	return TREN_H - (Math.max(0, Number(v) || 0) / maxTren.value) * TREN_H
}

const trenSeries = computed(() =>
	[
		{ key: 'fid', color: '#f97316' },
		{ key: 'fpd', color: '#dc2626' },
	].map((ser) => ({
		...ser,
		points: trenBulan.value
			.map((m, i) => `${trenX(i).toFixed(2)},${trenY(m[ser.key]).toFixed(2)}`)
			.join(' '),
	})),
)

const trenTitik = computed(() =>
	trenSeries.value.flatMap((ser) =>
		trenBulan.value.map((m, i) => ({
			key: `${ser.key}-${i}`,
			color: ser.color,
			x: trenX(i),
			y: trenY(m[ser.key]),
		})),
	),
)

const trenGrid = computed(() => {
	const langkah = maxTren.value / 4
	return [0, 1, 2, 3, 4].map((i) => {
		const v = maxTren.value - langkah * i
		return { v, y: trenY(v) }
	})
})

// ---- Format & warna --------------------------------------------------------
function int(value) {
	if (value === null || value === undefined) return '—'
	return fmtNum(value, 0)
}

function pct(value) {
	if (value === null || value === undefined) return 'n/a'
	return `${fmtNumFixed(value, 2)}%`
}

/** Selisih persentase; FID/FPD naik itu buruk, jadi tandanya apa adanya. */
function deltaPoin(value) {
	if (value === null || value === undefined) return 'n/a'
	const n = Number(value)
	if (!Number.isFinite(n)) return 'n/a'
	return `${n > 0 ? '+' : ''}${fmtNumFixed(n, 2)} poin`
}

// Ambang rasio risiko: makin kecil makin baik.
function rasioClass(value) {
	const p = Number(value)
	if (!Number.isFinite(p)) return 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
	if (p <= 5) return 'bg-ui-surface-green-50 text-ui-ink-green-600'
	if (p <= 15) return 'bg-ui-surface-amber-50 text-ui-ink-amber-600'
	return 'bg-ui-surface-red-50 text-ui-ink-red-600'
}

function selBulan(i, mode) {
	const matriks = mode === 'fpd' ? heatmap.value?.matrix_fpd : heatmap.value?.matrix_fid
	return matriks?.[i]
}

function selTeks(sel, display) {
	if (!sel || !sel.denominator) return ''
	return display === 'unit' ? fmtNum(sel.unit, 0) : `${fmtNum(sel.pct, 1)}%`
}

function selJudul(sel) {
	if (!sel) return ''
	return `${fmtNum(sel.unit, 0)} unit · ${fmtNum(sel.pct, 1)}% dari ${fmtNum(sel.denominator, 0)}`
}

/** Sel heatmap: warna & ambangnya mengikuti desk, bukan gradasi buatan sendiri. */
function selStyle(sel, mode) {
	if (!sel || !sel.denominator) return { background: '#f1f5f9', color: '#cbd5e1' }
	const ambang = HEATMAP_AMBANG[mode] || HEATMAP_AMBANG.fid
	const p = Number(sel.pct) || 0
	const i = ambang.findIndex((batas) => p <= batas)
	const warna = HEATMAP_PALET[i === -1 ? HEATMAP_PALET.length - 1 : i]
	return { background: warna.bg, color: warna.fg }
}

// ---- Aksi ------------------------------------------------------------------
function openFilter() {
	Object.assign(draft, filters)
	showFilter.value = true
}

function resetFilter() {
	draft.bulan = now.getMonth() + 1
	draft.tahun = now.getFullYear()
}

function applyFilter() {
	Object.assign(filters, draft)
	if (filters.bulan === now.getMonth() + 1 && filters.tahun === now.getFullYear()) {
		listPersistence.clearSession()
	} else {
		listPersistence.writeSession({ filters })
	}
	showFilter.value = false
	loadAll()
}

async function setHeatmap({ kategori: kat, grace }) {
	if (kat !== undefined) {
		if (heatmapKategori.value === kat) return
		heatmapKategori.value = kat
	}
	if (grace !== undefined) {
		if (heatmapGrace.value === grace) return
		heatmapGrace.value = grace
	}
	await loadHeatmap()
}

async function loadHeatmap() {
	try {
		heatmap.value = await call(`${API}.get_heatmap`, {
			tahun: filters.tahun,
			kategori: heatmapKategori.value,
			grace_period: heatmapGrace.value,
		})
	} catch (e) {
		heatmap.value = null
		notifyError(e, 'Gagal memuat heatmap')
	}
}

async function loadAll() {
	loading.value = true
	try {
		if (!opsi.value) opsi.value = await call(`${API}.get_filter_options`)
		const periode = { bulan: filters.bulan, tahun: filters.tahun }
		const [k, pv, l, b] = await Promise.all([
			call(`${API}.get_kpi_current`, periode),
			call(`${API}.get_kpi_previous`, periode),
			call(`${API}.get_line_chart`, { tahun: filters.tahun }),
			call(`${API}.get_breakdown`, periode),
		])
		kpi.value = k
		prev.value = pv
		line.value = l
		breakdown.value = b
		fatalError.value = ''
		await loadHeatmap()
	} catch (e) {
		if (!kpi.value) fatalError.value = errorText(e)
		else notifyError(e, 'Gagal memuat CMO Dashboard FID / FPD')
	} finally {
		loading.value = false
	}
}

async function reload() {
	if (loading.value) return
	await loadAll()
}

// Pesan Frappe datang sebagai `messages` (list HTML) atau `message`.
function errorText(e) {
	const raw = e?.messages?.join(' ') || e?.message || ''
	const text = String(raw)
		.replace(/<[^>]*>/g, ' ')
		.replace(/\s+/g, ' ')
		.trim()
	return text || 'Anda tidak punya akses ke dashboard ini.'
}

onMounted(async () => {
	await refreshCsrfToken()
	try {
		opsi.value = await call(`${API}.get_filter_options`)
	} catch {}
	const saved = listPersistence.readSession({
		filters: { bulan: now.getMonth() + 1, tahun: now.getFullYear() },
	}).filters
	if (saved.bulan >= 1 && saved.bulan <= 12) filters.bulan = saved.bulan
	if (yearOptions.value.includes(saved.tahun)) filters.tahun = saved.tahun
	await loadAll()
})
</script>
